    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([9, 4, 3, 8, 7, 2, 5]), fmt([0]), fmt([7]), fmt([2, 2, 2]), fmt([1, 3, 5]), fmt([5, 3, 1]), fmt([1, 2]), fmt([2, 1]), fmt([4, 4, 3, 3, 0, 1])]
    for n in range(2, 13):
        for _ in range(2):
            tests.append(fmt([rng.randint(0, 20) for _ in range(n)]))
    for _ in range(4):
        n = rng.randint(20, 40)
        tests.append(fmt([rng.randint(0, 10**6) for _ in range(n)]))
    N = 10**5
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(N)]))
    tests.append(fmt([2 * rng.randint(0, 5 * 10**8) + 1 for _ in range(N)]))
    tests.append(fmt([2 * rng.randint(0, 5 * 10**8) for _ in range(N)]))
    tests.append(fmt([(10**9 - i) if i % 2 else i for i in range(N)]))
    tests.append(fmt([rng.randint(0, 10) for _ in range(N)]))
    return tests
